alter  table   CHB_ASSET_INFO ADD  (CONSTRACTE_BUSI_TYPE  VARCHAR2(2 BYTE));
COMMENT ON COLUMN CHB_ASSET_INFO.CONSTRACTE_BUSI_TYPE IS '结构化业务类型';
alter  table   CHB_ASSET_INFO ADD  (CONSTRACTE_GRADE   VARCHAR2(2 BYTE));
