alter  table   CHB_ASSET_INFO ADD  (CONSTRACTE_HEAVER_TIMES NUMBER(8,5));
COMMENT ON COLUMN CHB_ASSET_INFO.CONSTRACTE_HEAVER_TIMES IS '结构化杠杆倍数';

